get_func_at_line() {
    local file="$1"
    local line="$2"
    awk -v target="$line" '
        BEGIN { current_func = "" }
        /^func / && NR <= target { 
            # Extract function name
            match($0, /func \(([^)]*)\) ([a-zA-Z_][a-zA-Z0-9_]*)/, arr)
            if (!arr[2]) {
                # Try receiver method pattern: func (r *Type) methodName
                match($0, /func \([^)]*\) ([a-zA-Z_][a-zA-Z0-9_]*)/, arr)
            }
            if (arr[2]) {
                current_func = arr[2]
            } else if (arr[1]) {
                current_func = arr[1]
            }
        }
        NR == target { print current_func; exit }
    ' "$file"
}

